   614  static int multiline_load_regex_rules(struct flb_ml_parser *ml_parser,
   615                                        struct flb_cf_section *section,
   616                                        struct flb_config *config)
   617  {
   618      int ret;
   619      char *to_state = NULL;
   620      struct mk_list list;
   621      struct mk_list *head;
   622      struct flb_kv *entry;
   623      struct flb_slist_entry *from_state;
   624      struct flb_slist_entry *regex_pattern;
   625      struct flb_slist_entry *tmp;
   626
   627      mk_list_foreach(head, &section->properties) {
   628          entry = mk_list_entry(head, struct flb_kv, _head);
   629
   630          /* only process 'rule' keys */
   631          if (strcasecmp(entry->key, "rule") != 0) {
   632              continue;
   633          }
   634
   635          mk_list_init(&list);
   636          ret = flb_slist_split_tokens(&list, entry->val, 3);
   637          if (ret == -1) {
   638              flb_error("[multiline parser: %s] invalid section on key '%s'",
   639                        ml_parser->name, entry->key);
   640              return -1;
   641          }
   642
   643          /* Get entries from the line */
   644          from_state    = flb_slist_entry_get(&list, 0);
   645          regex_pattern = flb_slist_entry_get(&list, 1);
   646          tmp = flb_slist_entry_get(&list, 2);
   647          if (tmp) {
   648              to_state  = tmp->str;
   649          }
   650          else {
   651              to_state = NULL;
   652          }
   653
   654          if (!from_state) {
   655              flb_error("[multiline parser: %s] 'from_state' is mandatory",
   656                        ml_parser->name);
   657              flb_slist_destroy(&list);
   658              return -1;
   659          }
   660
   661          if (!regex_pattern) {
   662              flb_error("[multiline parser: %s] 'regex_pattern' is mandatory",
   663                        ml_parser->name);
   664              flb_slist_destroy(&list);
   665              return -1;
   666          }
   667
   668          ret = flb_ml_rule_create(ml_parser,
   669                                   from_state->str,
   670                                   regex_pattern->str,
   671                                   to_state,
   672                                   NULL);
   673          if (ret == -1) {
   674              flb_error("[multiline parser: %s] error creating rule",
   675                        ml_parser->name);
   676              flb_slist_destroy(&list);
   677              return -1;
   678          }
   679
   680          flb_slist_destroy(&list);
   681      }
   682
   683      /* Map the rules (mandatory for regex rules) */
   684      ret = flb_ml_parser_init(ml_parser);
   685      if (ret != 0) {
   686          flb_error("[multiline parser: %s] invalid mapping rules, check the states",
   687                    ml_parser->name);
   688          return -1;
   689      }
   690
   691      return 0;
   692  }
