   106  /*
   107   * Helper function to simulate a fgets(2) but instead of using a real file stream
   108   * uses the data buffer provided.
   109   */
   110  static int static_fgets(char *out, size_t size, const char *data, size_t *off)
   111  {
   112      size_t len;
   113      const char *start = data + *off;
   114      char *end;
   115
   116      end = strchr(start, '\n');
   117
   118      if (!end || *off >= size) {
   119          len = size - *off - 1;
   120          memcpy(out, start, len);
   121          out[len] = '\0';
   122          *off += len + 1;
   123          return 0;
   124      }
   125
   126      len = end - start;
   127      if (len >= size) {
   128          len = size - 1;
   129      }
   130      memcpy(out, start, len);
   131      out[len] = '\0';
   132      *off += len + 1;
   133
   134      return 1;
   135  }
